$m = epc_sso_sp_metadata('Acme-Site');
$xml = epc_sso_sp_metadata_xml('Acme-Site');
$ar = epc_sso_authn_request('Acme-Site', array('sso_url' => 'https://idp.example.com/sso?x=1&y=2'));
$ar['request_id'] = 'FIXED';
$ar['raw_request'] = preg_replace('/ID="[^"]+"/', 'ID="FIXED"', $ar['raw_request']);
$ar['raw_request'] = preg_replace('/IssueInstant="[^"]+"/', 'IssueInstant="FIXED"', $ar['raw_request']);
$ar['redirect_url'] = (strpos($ar['redirect_url'], 'https://idp.example.com/sso') === 0 && strpos($ar['redirect_url'], 'SAMLRequest=') !== false) ? 'HAS_SAML' : 'NO';
return array(EPC_SSO_SAML_VERSION, $m, $xml, $ar);

$pdo = $GLOBALS['db_link'];
epc_sso_ensure_schema($pdo);
$miss = epc_sso_provider_get($pdo, 9);
$c1 = epc_sso_provider_create($pdo, 'acme', array('provider_name'=>'Zed IdP','sso_url'=>'https://idp.z/sso','active'=>0,'created_by'=>4));
$c2 = epc_sso_provider_create($pdo, 'acme', array('provider_name'=>'Acme IdP','sso_url'=>'https://idp.a/sso','active'=>1,'jit_provision'=>0,'default_role'=>'staff'));
$c3 = epc_sso_provider_create($pdo, 'other', array('provider_name'=>'Other'));
$hit = epc_sso_provider_get($pdo, (int)$c2['provider_id']);
unset($hit['created_at'], $hit['updated_at'], $hit['certificate'], $hit['metadata_xml']);
$list = epc_sso_provider_list($pdo, 'acme');
foreach ($list as &$r) { unset($r['updated_at']); }
$tog = epc_sso_provider_toggle($pdo, (int)$c1['provider_id'], true);
$del = epc_sso_provider_delete($pdo, (int)$c3['provider_id']);
$_SERVER['REMOTE_ADDR'] = '10.1.2.3';
$_SERVER['HTTP_USER_AGENT'] = 'Mozilla/5.0';
$ok = epc_sso_process_response($pdo, 'acme', '', (int)$c2['provider_id']);
$nof = epc_sso_process_response($pdo, 'acme', '', 99);
$bad = epc_sso_process_response($pdo, 'acme', 'bm90LXhtbA==', (int)$c2['provider_id']);
$fail = epc_sso_process_response($pdo, 'acme', '', (int)$c2['provider_id']);
$sess = epc_sso_active_sessions($pdo, 'acme');
foreach ($sess as &$s) { unset($s['login_at'], $s['logout_at'], $s['expires_at']); }
$lo = epc_sso_logout($pdo, (int)$ok['session_id']);
$pdo->exec("INSERT INTO epc_sso_sessions (site_key,provider_id,name_id,email,attributes,session_index,status,expires_at) VALUES ('acme',1,'x','x@x.com','{}','','active','2000-01-01 00:00:00')");
$exp = epc_sso_expire_old($pdo);
$fleet = epc_sso_fleet_stats($pdo);
return array($miss, $c1, $c2, $hit, $list, $tog, $del, $ok, $nof, $bad, $fail, $sess, $lo, $exp, $fleet);

